CREATE OR REPLACE TABLE TAG_MASTER_1 (
	DAT DATE NOT NULL COMMENT 'Datum im Format JJJJ-MM_1-TT',
	KJMO NUMBER(38,0) NOT NULL COMMENT 'Monat_1 eines Kalenderjahres, Format JJJJMM',
	KJMO_VJ NUMBER(38,0) NOT NULL COMMENT 'Der einem Kalenderjahresmonat entspreche Monat_1 des Kalendervorjahres, Format JJJJMM',
	KJMO_VVJ NUMBER(38,0) NOT NULL COMMENT 'Kalendermonat im Vorvorjahr',
	WTAG_ID NUMBER(38,0) NOT NULL COMMENT 'laufende Nummer des Wochentages, wobei Montag = 1 und Sonntag = 7',
	KJWO NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahreswoche, Format JJJJWW',
	KJWO_VJ NUMBER(38,0) NOT NULL COMMENT 'Die der Kalenderjahreswoche entsprechende Woche_1 im Vorjahr, Format JJJJWW',
	KJWO_VVJ NUMBER(38,0) NOT NULL COMMENT 'Kalenderwoche im Vorvorjahr',
	GJWO NUMBER(38,0) NOT NULL COMMENT 'Geschäftsjahreswoche. Kann zwischen 1 und 53 sein, 1 beginnt zum Geschäftsjahr. Format JJJJWW',
	GJWO_VJ NUMBER(38,0) NOT NULL COMMENT 'Der Geschäftsjahrewoche entsprechende Woche_1 im Vorjahr, Format JJJJWW',
	WO_DAT_VON DATE NOT NULL COMMENT 'Datum des ersten Tages der Woche_1 im Format JJJJ-MM_1-TT',
	WO_DAT_BIS DATE NOT NULL COMMENT 'Datum des letzten Tages der Woche_1 im Format JJJJ-MM_1-TT',
	GJMO NUMBER(38,0) NOT NULL COMMENT 'Geschäftsjahresmonat, beginnend bei 1 im März, Format JJJJMM',
	GJMO_VJ NUMBER(38,0) NOT NULL COMMENT 'Der einem Geschäftsjahresmonat entsprechende Monat_1 des Vorjahres, Format JJJJMM',
	KJQU NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahresquartal, Format JJJJQQ',
	GJQU NUMBER(38,0) NOT NULL COMMENT 'Geschäftsjahresquartal, Format JJJJQQ',
	KJ NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahr, Format JJJJ',
	GJ NUMBER(38,0) NOT NULL COMMENT 'Geschäftsjahr, Format JJJJ',
	KJTAG_ID NUMBER(38,0) NOT NULL COMMENT 'Laufende Nummer des Tages im Kalenderjahr, von 1 bis 365 bzw. 366',
	GJTAG_ID NUMBER(38,0) NOT NULL COMMENT 'Laufende Nummer des Tages im Geschäftsjahr, von 1 bis 365 bzw. 366',
	KJWO_KL NUMBER(38,0) NOT NULL COMMENT 'Kaufland - Kalenderjahreswoche. Beginnt am 01.01. eines Jahres und endet am 31.12. unabhängig vom Wochentag. Die erste und die letzte Kalenderjahreswoche enthält so in der Regel weniger als sieben Tage. Format JJJJWW',
	KJWO_KL_DAT_VON DATE NOT NULL COMMENT 'Datum des Beginns einer Kaufland Kalenderjahreswoche. Format JJJJ-MM_1-TT',
	KJWO_KL_DAT_BIS DATE NOT NULL COMMENT 'Datum des Endes einer Kaufland Kalenderjahreswoche. Format JJJJ-MM_1-TT',
	GJWO_KL NUMBER(38,0) NOT NULL COMMENT 'Kaufland - Geschäftsjahreswoche. Beginnt am 01.03. eines Jahres und endet letzten Februartag unabhängig vom Wochentag. Die erste und die letzte Geschäftsjahreswoche enthält so in der Regel weniger als sieben Tage. Format JJJJWW',
	GJWO_KL_DAT_VON DATE NOT NULL COMMENT 'Datum des Beginns einer Kaufland Geschäftsjahreswoche. Format JJJJ-MM_1-TT',
	GJWO_KL_DAT_BIS DATE NOT NULL COMMENT 'Datum des Endes einer Kaufland Geschäftsjahreswoche. Format JJJJ-MM_1-TT',
	DAT_VJ DATE NOT NULL COMMENT 'dem Tagesdatum entsprechendes Datum im Vorjahr',
	DAT_VVJ DATE NOT NULL DEFAULT CAST('1900-01-01' AS DATE) COMMENT 'Wochentag im Vorvorjahr',
	AKT_TAG NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Tages zum laufenden Tag_1 darstellt. Der aktuelle Tag_1 hat den Wert 0, der vorige Tag_1 -1 und der nächste Tag_1 den Wert 1',
	AKT_MO NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Monats zum laufenden Monat_1 darstellt. Der aktuelle Monat_1 hat den Wert 0, der vorige Monat_1 -1 und der nächste Monat_1 den Wert 1',
	AKT_MO_KOMPLETT NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Monats zum letzten abgeschlossenen Monat_1 darstellt. Der aktuelle Monat_1 hat den Wert 1, der vorige Monat_1 0 und der nächste Monat_1  den Wert 2',
	AKT_WO NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand einer Woche_1 zur laufenden Woche_1 darstellt. Die aktuelle Woche_1 hat den Wert 0, die vorige Woche_1 -1 und die nächste Woche_1 den Wert 1',
	AKT_WO_KOMPLETT NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand einer Woche_1 zur letzten abgeschlossenen Woche_1 darstellt. Die aktuelle Woche_1 hat den Wert 1, die vorige Woche_1 0 und die nächste Woche_1  den Wert 2',
	AKT_GJWO_KL NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand einer Geschäftjahreswoche KL  zur laufenden GJWoche KL darstellt. Die aktuelle GJWoche KL  hat den Wert 0, die vorige GJwoche KL -1 und die nächste GJWoche KL den Wert 1',
	AKT_GJWO_KL_KOMPLETT NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand einer Geschäftjahreswoche KL  zur laufenden abgeschlossenen GJWoche KL darstellt. Die aktuelle GJWoche KL  hat den Wert 1, die vorige GJwoche KL 0 und die nächste GJWoche KL den Wert 2',
	AKT_KJWO_KL NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand einer  Kalenderjahreswoche Kaufland zur aktuellen kjwo_kl anzeigt. Die aktuelle Kjwo_kl hat den Wert 0, die vorige Kjwo_kl -1 und die nächste Kjwo_kl den Wert 1',
	AKT_KJWO_KL_KOMPLETT NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand einer  Kalenderjahreswoche Kaufland zur letzten abgeschlossenen kjwo_kl anzeigt. Die aktuelle Kjwo_kl hat den Wert 1, die vorige Kjwo_kl 0 und die nächste Kjwo_kl den Wert 2',
	AKT_GJQU NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Geschäftjahresquartals  zum laufenden GJQuartal darstellt. Das aktuelle GJQuartal  hat den Wert 0, das vorige GJQuartal -1 und das nächste GJQuartal den Wert 1',
	AKT_GJQU_KOMPLETT NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines GeschäftjahresQuartals  zum letzten abgeschlossenen GJQuartal  darstellt. Das aktuelle GJQuartal  hat den Wert 1, das vorige GJQuartal  0 und das nächste GJQuartal  den Wert 2',
	AKT_KJQU NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Kalenderjahresquartals  zum laufenden KJQuartal darstellt. Das aktuelle KJQuartal  hat den Wert 0, das vorige KJQuartal -1 und das nächste KJQuartal den Wert 1',
	AKT_KJQU_KOMPLETT NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines KalenderahresQuartals  zum letzten abgeschlossenen KJQuartal  darstellt. Das aktuelle KJQuartal  hat den Wert 1, das vorige KJQuartal  0 und das nächste KJQuartal  den Wert 2',
	AKT_GJ NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Geschäftjahres zum laufenden GJ darstellt. Das aktuelle GJ hat den Wert 0, das vorige GJ -1 und das nächste GJ den Wert 1',
	AKT_GJ_KOMPLETT NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Geschäftjahres zum letzten abgeschlossenen GJ darstellt. Das aktuelle GJ hat den Wert 1, das vorige GJ 0 und das nächste GJ den Wert 2',
	AKT_KJ NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Kalenderjahres zum laufenden KJ darstellt. Das aktuelle KJ hat den Wert 0, das vorige KJ -1 und das nächste KJ den Wert 1',
	AKT_KJ_KOMPLETT NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Kalenderjahres zum letzten abgeschlossenen KJ darstellt. Das aktuelle KJ hat den Wert 1, das vorige KJ 0 und das nächste KJ den Wert 2',
	MO_GJ NUMBER(38,0) NOT NULL COMMENT 'Laufender Monat_1 im Geschäftsjahr. Wert zwischen 1 und 12, wobei März = 1 und Februar = 12',
	MO_KJ NUMBER(38,0) NOT NULL COMMENT 'Laufender Monat_1 im Kalenderjahr. Wert zwischen 1 und 12, wobei Januar = 1 und Dezember = 12',
	PJWO NUMBER(38,0) NOT NULL COMMENT 'Produktionswoche, geht von Samstag bis Freitag',
	GJHJ NUMBER(38,0) NOT NULL COMMENT 'Geschäftsjahres-Halbjahr (Format Jahr Halbjahr Bsp. 201701)',
	AKT_GJHJ NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Geschäftjahres-Halbjahr  zum laufenden GJ-Halbjahr darstellt. Das aktuelle GJ-Halbjahr  hat den Wert 0, das vorige GJ-Halbjahr -1 und das nächste GJ-Halbjahr den Wert 1',
	AKT_GJHJ_KOMPLETT NUMBER(38,0) NOT NULL COMMENT 'Zahlenfolge, die den Abstand eines Geschäftjahres-Halbjahr  zum letzten abgeschlossenen GJ-Halbjahr darstellt. Das aktuelle GJ-Halbjahr  hat den Wert 0, das vorige GJ-Halbjahr -1 und das nächste GJ-Halbjahr den Wert 1',
	DAT_VJ_KT DATE COMMENT 'Vorjahresdatum auf Kalendertagesebene (KT). Hat das gleiche Datum im Vorjahr, z.B. wenn DAT = ''2020-01-01'' dann DAT_VJ_KT = ''2019-01-01''. Ist beim Schalttag leer, z.B.: DAT = ''2020-02-29'' dann DAT_VJ_KT = null. (Im Gegensatz dazu sind DAT_VJ und DAT_VVJ auf Wochentagesebene, also wenn das betrachtete Datum ein Dienstag ist, dann beinhalten DAT_VJ das Datum für den Dienstag 52 Wochen oder 364 Tage zurück.)',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_TAG_MASTER primary key (DAT)
)COMMENT='Zeit_1 - Ladehilfstabelle.Enthält Kalenderdaten auf Tagesebene'
;